{
  "name": "query_erpnext_data",
  "description": "Query ERPNext/Frappe records from any available DocType. Use this tool whenever the user asks to find, search, list, show, retrieve, count, total, sum, filter, sort, compare, or summarize ERPNext data. The database is the source of truth.",
  "parameters": {
    "type": "object",
    "properties": {
      "operation": {
        "type": "string",
        "enum": [
          "list",
          "count",
          "sum"
        ],
        "description": "list retrieves matching records, count returns the exact number of all matching records, and sum returns the exact total of a numeric field across all matching records."
      },
      "doctype": {
        "type": "string",
        "description": "Exact ERPNext/Frappe DocType name. Must exist in the available DocType list. Never invent a DocType."
      },
      "fields": {
        "type": "array",
        "description": "Actual fieldnames from the selected DocType. Use only fields that exist. For count and sum, include the minimum fields necessary to perform or describe the operation.",
        "items": {
          "type": "string"
        },
        "minItems": 1
      },
      "filters": {
        "type": "object",
        "description": "JSON object containing ERPNext/Frappe filters. Use {} when no filters are required. Multiple filters are combined with AND logic.",
        "additionalProperties": true
      },
      "order_by": {
        "type": "string",
        "description": "Optional sorting expression, for example 'grand_total desc', 'posting_date desc', or 'creation asc'. Primarily used with list operations. Use 'desc' for top/highest/descending and 'asc' for bottom/lowest/ascending. Do not include trailing commas or words other than 'asc' or 'desc'."
      },
      "limit": {
        "type": "integer",
        "description": "Maximum number of records returned for a list operation. If user specifies a number or limit (e.g. 'top 10', '10 records', 'first 5'), set limit to that exact number. Do not use limit to restrict count or sum calculations.",
        "minimum": 1
      },
      "offset": {
        "type": "integer",
        "description": "Number of matching records to skip for pagination. Use only for list operations. Start at 0.",
        "minimum": 0
      },
      "sum_field": {
        "type": "string",
        "description": "Actual numeric ERPNext field to sum when operation is sum. Must exist in the selected DocType."
      }
    },
    "required": [
      "operation",
      "doctype",
      "fields",
      "filters"
    ],
    "additionalProperties": false
  }
}
